{"command":"cat <<'EOF' > style.go
package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type ColorString struct {
	codeFG string
	codeBG string
	raw    string
}

func (c *ColorString) UnmarshalYAML(value *yaml.Node) error {
	var str string
	if err := value.Decode(&str); err != nil {
		return err
	}
	c.raw = str
	if str == "" {
		c.codeFG = ""
		c.codeBG = ""
		return nil
	}

	fg, bg, ok := parseColor(str)
	if !ok {
		return fmt.Errorf("invalid format")
	}
	c.codeFG = fg
	c.codeBG = bg
	return nil
}

var (
	reHex = regexp.MustCompile(`^#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})$`)
	reRGB = regexp.MustCompile(`^rgb\(\s*(0x[0-9a-fA-F]+|\d+)\s*,\s*(0x[0-9a-fA-F]+|\d+)\s*,\s*(0x[0-9a-fA-F]+|\d+)\s*\)$`)
)

func parseColorNum(s string) (int64, error) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		return strconv.ParseInt(s[2:], 16, 64)
	}
	return strconv.ParseInt(s, 10, 64)
}

func parseColor(str string) (string, string, bool) {
	str = strings.TrimSpace(str)

	// Standard color names map
	var fgMap = map[string]string{
		"black":        "30",
		"red":          "31",
		"green":        "32",
		"yellow":       "33",
		"blue":         "34",
		"magenta":      "35",
		"cyan":         "36",
		"white":        "37",
		"lightBlack":   "90",
		"lightRed":     "91",
		"lightGreen":   "92",
		"lightYellow":  "93",
		"lightBlue":    "94",
		"lightMagenta": "95",
		"lightCyan":    "96",
		"lightWhite":   "97",
	}

	var bgMap = map[string]string{
		"black":        "40",
		"red":          "41",
		"green":        "42",
		"yellow":       "43",
		"blue":         "44",
		"magenta":      "45",
		"cyan":         "46",
		"white":        "47",
		"lightBlack":   "100",
		"lightRed":     "101",
		"lightGreen":   "102",
		"lightYellow":  "103",
		"lightBlue":    "104",
		"lightMagenta": "105",
		"lightCyan":    "106",
		"lightWhite":   "107",
	}

	if fg, ok := fgMap[str]; ok {
		return fg, bgMap[str], true
	}

	if m := reHex.FindStringSubmatch(str); m != nil {
		r, _ := strconv.ParseInt(m[1], 16, 64)
		g, _ := strconv.ParseInt(m[2], 16, 64)
		b, _ := strconv.ParseInt(m[3], 16, 64)
		fg := fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
		bg := fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
		return fg, bg, true
	}

	if m := reRGB.FindStringSubmatch(str); m != nil {
		r, err1 := parseColorNum(m[1])
		g, err2 := parseColorNum(m[2])
		b, err3 := parseColorNum(m[3])
		if err1 == nil && err2 == nil && err3 == nil && r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255 {
			fg := fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
			bg := fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
			return fg, bg, true
		}
	}

	return "", "", false
}

type Style struct {
	Hide       bool        `yaml:"hide"`
	Bold       bool        `yaml:"bold"`
	Faint      bool        `yaml:"faint"`
	Italic     bool        `yaml:"italic"`
	Underline  bool        `yaml:"underline"`
	BlinkSlow  bool        `yaml:"blinkSlow"`
	BlinkRapid bool        `yaml:"blinkRapid"`
	Inverse    bool        `yaml:"inverse"`
	Conceal    bool        `yaml:"conceal"`
	CrossOut   bool        `yaml:"crossOut"`
	Frame      bool        `yaml:"frame"`
	Encircle   bool        `yaml:"encircle"`
	Overline   bool        `yaml:"overline"`
	Foreground ColorString `yaml:"foreground"`
	Background ColorString `yaml:"background"`
}

func (s Style) ESCCodes() string {
	var codes []string
	if s.Background.codeBG != "" {
		codes = append(codes, s.Background.codeBG)
	}
	if s.Foreground.codeFG != "" {
		codes = append(codes, s.Foreground.codeFG)
	}
	if s.Bold {
		codes = append(codes, "1")
	}
	if s.Faint {
		codes = append(codes, "2")
	}
	if s.Italic {
		codes = append(codes, "3")
	}
	if s.Underline {
		codes = append(codes, "4")
	}
	if s.BlinkSlow {
		codes = append(codes, "5")
	}
	if s.BlinkRapid {
		codes = append(codes, "6")
	}
	if s.Inverse {
		codes = append(codes, "7")
	}
	if s.Conceal {
		codes = append(codes, "8")
	}
	if s.CrossOut {
		codes = append(codes, "9")
	}
	if s.Frame {
		codes = append(codes, "51")
	}
	if s.Encircle {
		codes = append(codes, "52")
	}
	if s.Overline {
		codes = append(codes, "53")
	}

	if len(codes) == 0 {
		return ""
	}

	var sb strings.Builder
	for _, c := range codes {
		sb.WriteString("\x1b[")
		sb.WriteString(c)
		sb.WriteString("m")
	}
	return sb.String()
}

func (s Style) Apply(text string) string {
	esc := s.ESCCodes()
	if esc == "" {
		return text
	}
	return esc + text + "\x1b[0m"
}
EOF"}

