{"command":"cat <<'EOF' > main.go
package main

import (
	"io"
	"os"
	"os/exec"
)

func isColorEnabled() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") != "" {
		return true
	}
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func runTestFilter() {
	if !isColorEnabled() {
		io.Copy(os.Stdout, os.Stdin)
		return
	}
	cfg := LoadConfig()
	filter := NewFilter(cfg)
	filter.Process(os.Stdin, os.Stdout)
}

func runGoTest(args []string) {
	goBin, err := exec.LookPath("go")
	if err != nil {
		goBin = "go"
	}

