package main

import (
	"bufio"
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"
)

var (
	reStart    = regexp.MustCompile(`^=== RUN   (Test\S*)(.*)$`)
	rePass     = regexp.MustCompile(`^--- PASS: (Test\S*)(.*)$`)
	reFail     = regexp.MustCompile(`^--- FAIL: (Test\S*)(.*)$`)
	reSkip     = regexp.MustCompile(`^--- SKIP: (Test\S*)(.*)$`)
	reBuild    = regexp.MustCompile(`^# (.*)$`)
	reCover    = regexp.MustCompile(`^coverage: ([0-9.]+)% of statements$`)
	reOk       = regexp.MustCompile(`^ok\s+(\S+)(?:\s+(?:[0-9.]+[smhµ]|\(cached\)))?(?:\s+\[no tests to run\])?(?:\s+(coverage: [0-9.]+% of statements))?$`)
	reFailPkg  = regexp.MustCompile(`^FAIL\t(\S+)\s+(.*)$`)
	reFileLine = regexp.MustCompile(`([a-zA-Z0-9_\-./]+\.go):(\d+(?::\d+)?)`)
)

type Filter struct {
	cfg         Config
	activeStyle Style
	removals    []*regexp.Regexp
}

func NewFilter(cfg Config) *Filter {
	var rems []*regexp.Regexp
	for _, r := range cfg.Removals {
		if re, err := regexp.Compile(r); err == nil {
			rems = append(rems, re)
		}
	}
	return &Filter{
		cfg:      cfg,
		removals: rems,
	}
}

func (f *Filter) Process(r io.Reader, w io.Writer) error {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()

		for _, re := range f.removals {
			line = re.ReplaceAllString(line, "")
		}

		outLine, show := f.processLine(line)
		if show {
			fmt.Fprintln(w, outLine)
		}
	}
	return scanner.Err()
}

func (f *Filter) getLabel(kind string) string {
	switch f.cfg.LabelType {
	case "short":
		switch kind {
		case "start":
			return ">  "
		case "pass":
			return "o  "
		case "fail":
			return "x  "
		case "skip":
			return "-  "
		case "build":
			return "!! "
		case "cover":
			return "%  "
		default:
			return "   "
		}
	case "none":
		return ""
	default: // "long"
		switch kind {
		case "start":
			return "START| "
		case "pass":
			return "PASS | "
		case "fail":
			return "FAIL | "
		case "skip":
			return "SKIP | "
		case "build":
			return "BUILD| "
		case "cover":
			return "COVER| "
		default:
			return "     | "
		}
	}
}

func (f *Filter) processLine(line string) (string, bool) {
	// 1. Start
	if m := reStart.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.StartStyle
		if f.cfg.StartStyle.Hide {
			return "", false
		}
		testName := m[1]
		if !f.cfg.LeaveTestPrefix {
			testName = strings.TrimPrefix(testName, "Test")
		}
		indent := strings.Repeat("  ", strings.Count(testName, "/"))
		formatted := indent + testName + m[2]
		return f.cfg.StartStyle.Apply(f.getLabel("start") + formatted), true
	}

	// 2. Pass
	if m := rePass.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.PassStyle
		if f.cfg.PassStyle.Hide {
			return "", false
		}
		testName := m[1]
		if !f.cfg.LeaveTestPrefix {
			testName = strings.TrimPrefix(testName, "Test")
		}
		indent := strings.Repeat("  ", strings.Count(testName, "/"))
		formatted := indent + testName + m[2]
		return f.cfg.PassStyle.Apply(f.getLabel("pass") + formatted), true
	}

	// 3. Fail
	if m := reFail.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.FailStyle
		if f.cfg.FailStyle.Hide {
			return "", false
		}
		testName := m[1]
		if !f.cfg.LeaveTestPrefix {
			testName = strings.TrimPrefix(testName, "Test")
		}
		indent := strings.Repeat("  ", strings.Count(testName, "/"))
		formatted := indent + testName + m[2]
		return f.cfg.FailStyle.Apply(f.getLabel("fail") + formatted), true
	}

	// 4. Skip
	if m := reSkip.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.SkipStyle
		if f.cfg.SkipStyle.Hide {
			return "", false
		}
		testName := m[1]
		if !f.cfg.LeaveTestPrefix {
			testName = strings.TrimPrefix(testName, "Test")
		}
		indent := strings.Repeat("  ", strings.Count(testName, "/"))
		formatted := indent + testName + m[2]
		return f.cfg.SkipStyle.Apply(f.getLabel("skip") + formatted), true
	}

	// 5. Build
	if m := reBuild.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.BuildStyle
		if f.cfg.BuildStyle.Hide {
			return "", false
		}
		return f.cfg.BuildStyle.Apply(f.getLabel("build") + m[1]), true
	}

	// 6. Cover
	if m := reCover.FindStringSubmatch(line); m != nil {
		p, _ := strconv.ParseFloat(m[1], 64)
		st := f.cfg.UncoveredStyle
		if p >= f.cfg.CoverThreshold {
			st = f.cfg.CoveredStyle
		}
		f.activeStyle = st
		if st.Hide {
			return "", false
		}
		hashes := int(p / 10.0)
		if hashes > 10 {
			hashes = 10
		}
		underscores := 10 - hashes
		bar := "[" + strings.Repeat("#", hashes) + strings.Repeat("_", underscores) + "]"
		formattedText := fmt.Sprintf("%.1f%% %s", p, bar)
		return st.Apply(f.getLabel("cover") + formattedText), true
	}

	// 7. PassPackage ("PASS")
	if line == "PASS" {
		f.activeStyle = f.cfg.PassPackageStyle
		if f.cfg.PassPackageStyle.Hide {
			return "", false
		}
		return f.cfg.PassPackageStyle.Apply("PASS"), true
	}

	// 8. FailPackage ("FAIL")
	if line == "FAIL" {
		f.activeStyle = f.cfg.FailPackageStyle
		if f.cfg.FailPackageStyle.Hide {
			return "", false
		}
		return f.cfg.FailPackageStyle.Apply("FAIL"), true
	}

	// 9. OkPackage ("ok ...")
	if m := reOk.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.PassStyle
		if f.cfg.PassStyle.Hide {
			return "", false
		}
		body := m[1] + " "
		if m[2] != "" {
			body = m[1] + " " + m[2]
		}
		return f.cfg.PassStyle.Apply(f.getLabel("pass") + body), true
	}

	// 10. FailPackageLine ("FAIL\t...")
	if m := reFailPkg.FindStringSubmatch(line); m != nil {
		f.activeStyle = f.cfg.FailStyle
		if f.cfg.FailStyle.Hide {
			return "", false
		}
		body := "\t" + m[1] + "\t" + m[2]
		return f.cfg.FailStyle.Apply(f.getLabel("fail") + body), true
	}

	// 11. Log line (Default)
	activeEsc := f.activeStyle.ESCCodes()

	formattedLine := reFileLine.ReplaceAllStringFunc(line, func(match string) string {
		sub := reFileLine.FindStringSubmatch(match)
		if len(sub) < 3 {
			return match
		}
		filePart := f.cfg.FileStyle.Apply(sub[1])
		linePart := f.cfg.LineStyle.Apply(":" + sub[2])
		res := filePart + linePart
		if activeEsc != "" {
			res += activeEsc
		}
		return res
	})

	label := f.getLabel("default")

	if activeEsc != "" {
		return activeEsc + label + formattedLine + "\x1b[0m", true
	}

	return label + formattedLine, true
}
EOF

